css:
.btn {
  cursor: pointer;
  position: relative;
  padding: 0.5rem;
  border-radius: 1.5rem;

  transition:
    box-shadow 0.3s ease,
    border-color 0.3s ease;
  box-shadow:
    0 2px 1px 0 #fff0,
    0 2px 2px 0 #fff0,
    0 6px 6px 0 #fff0,
    0 24px 24px 0 #fff0,
    0 32px 32px 0 #fff0,
    inset 0 -1px 1px #0004,
    inset 0 -1px 16px #0004;
  border: 2px solid #ffffff02;
  background:
    radial-gradient(circle at 50% -100%, #fff3 0%, #0001 75%) 0 -4px / 200px 200px
      repeat,
    conic-gradient(
        #ffffff14 0.25turn,
        #ffffff20 0.25turn 0.5turn,
        #ffffff14 0.5turn 0.75turn,
        #ffffff20 0.75turn
      )
      top left / 4px 4px repeat,
    #111;
}

.btn .svg {
  width: 3rem;
  height: 3rem;
  transition: filter 0.3s ease;
  fill: #292929ee;
  filter: drop-shadow(0 -1px 0 #fff6) drop-shadow(0 1px 0 #0003)
    drop-shadow(0 -0px 1px #000a);
}

.btn .txt {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #fff7;
  font-size: 1.1rem;
  font-family: "Inter", sans-serif;
  letter-spacing: -0.035rem;
  transition:
    transform 0.5s ease,
    opacity 0.3s ease,
    text-shadow 0.3s ease,
    color 0.3s ease;
  transform: translateY(-125%);
  text-shadow:
    0 1px 1px #0000,
    0 2px 2px #0000,
    0 4px 4px #0000,
    0 16px 16px #0000;
  opacity: 0;
  pointer-events: none;
  user-select: none;
}

.btn:hover {
  box-shadow:
    0 -1px 1px 0 #fff8,
    0 -2px 2px 0 #fff3,
    0 -6px 6px 0 #fff3,
    0 -24px 24px 0 #fff2,
    0 -32px 32px 0 #fff2,
    inset 0 -1px 1px #0008,
    inset 0 -1px 16px #0008;
  border: 2px dotted #ffffff12;

  .txt {
    transform: translateY(-75%);
    text-shadow:
      0 -1px 1px #000,
      0 -2px 2px #000,
      0 -4px 4px #000,
      0 -16px 16px #000;
    opacity: 1;
  }
  .svg {
    filter: drop-shadow(0 -1px 0 #fffd) drop-shadow(0 1px 0 #0008)
      drop-shadow(0 -0px 1px #000e);
  }
}

.btn:active {
  box-shadow:
    0 -1px 1px 0 #fff4,
    0 -2px 2px 0 #fff1,
    0 -6px 6px 0 #fff1,
    0 -24px 24px 0 #fff1,
    0 -32px 32px 0 #fff0,
    inset 0 -1px 1px #0006,
    inset 0 -1px 16px #0006;
  .txt {
    color: #fff2;
  }
  .svg {
    filter: drop-shadow(0 -1px 0 #fff8) drop-shadow(0 1px 0 #0004)
      drop-shadow(0 -0px 1px #000c);
  }
}
